    # Find background color (most frequent)
    all_cells = [cell for row in grid for cell in row]
    bg = max(Counter(all_cells).items(), key=lambda x: x[1])[0]

    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Fill gaps between feature pixels horizontally and vertically
    for r in range(rows):
        # Find positions of non-background pixels in this row
        for i in range(cols):
            if grid[r][i] != bg:
                # Check the cell to the right for gaps
                for j in range(i + 1, cols):
                    if result[r][j] != bg:
                        break
                    result[r][j] = 2

    for c in range(cols):
        # Find positions of non-background pixels in this column
        for i in range(rows):
            if grid[i][c] != bg:
                # Check the cell below for gaps
                for j in range(i + 1, rows):
                    if result[j][c] != bg:
                        break
                    result[j][c] = 2

    return result
